@startuml

class Patient {
  + name : string
  + symptoms : string[]
}

class Doctor {
  + name : string
  + speciality : string
}

class Diagnosis {
  + id : int
  + description : string
  + priorityScore : string
  + stage : int
}

class TreatmentPlan {
  + id : int
  + treatmentDescription : string
  + stages : int
}

class Treatment {
  + id : int
  + diagnosisId : int
  + doctorId : int
  + stage : int
  + consentGiven : boolean
}

class PriorityStageUpgrade {
  + id : int
  + illnessId : int
  + newStage : int
}

Patient "1" -- "*" Diagnosis
Doctor "1" -- "*" Diagnosis
Diagnosis "1" -- "*" TreatmentPlan
TreatmentPlan "1" -- "*" Treatment
Diagnosis "0..*" -- "* PriorityStageUpgrade"

@enduml

